import {TYPES} from './domain.mjs';
import {entityIndex,entityContext,matchesEntity,sortEntities,paginate} from './navigation.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=null;
export function closeEntityPicker({restore=true}={}){if(!current)return;const {dialog,trigger}=current;current=null;dialog.close();dialog.remove();if(restore&&trigger?.isConnected)trigger.focus();}
export function openEntityPicker({title,description,selected='',records,state,allowAll=false,approved=false,onSelect,trigger=document.activeElement}){
 closeEntityPicker({restore:false});
 const dialog=document.createElement('dialog');dialog.className='entity-picker';dialog.setAttribute('aria-labelledby','entity-picker-title');
 dialog.innerHTML=`<header class="picker-header"><div><span class="eyebrow">FIND & SELECT</span><h2 id="entity-picker-title">${escape(title)}</h2><p>${escape(description||'Search by name, ID or parent. Select a record to use it.')}</p></div><button type="button" class="iconbtn" data-picker="close" aria-label="Close selector">✕</button></header><div class="picker-search"><label for="entity-picker-search">Search all records in this list</label><input id="entity-picker-search" type="search" placeholder="Name, record ID or parent…" autocomplete="off"></div><div id="picker-results"></div>`;
 document.body.append(dialog);current={dialog,trigger};let query='',page=1;const index=entityIndex(state);
 const draw=()=>{const candidates=sortEntities(records().filter(r=>matchesEntity(r,query,index,{approved}))),view=paginate(candidates,{page,pageSize:25});page=view.page;
 dialog.querySelector('#picker-results').innerHTML=`<div class="picker-results-meta" role="status">${view.total.toLocaleString()} matching records${selected&&selected!=='all'?' · Current selection: '+escape(index.get(selected)?.name||selected):''}</div><div class="picker-list">${allowAll?`<button type="button" class="picker-result ${selected==='all'?'selected':''}" data-picker="select" data-id="all"><span><strong>All ${escape(title.toLowerCase())}</strong><small>Remove this filter</small></span><span>${selected==='all'?'✓':'→'}</span></button>`:''}${view.items.map(r=>`<button type="button" class="picker-result ${selected===r.id?'selected':''}" data-picker="select" data-id="${escape(r.id)}" aria-label="Select ${escape(r.name)}, ${escape(r.code)}"><span><strong>${escape(r.name)}</strong><small>${escape(r.code)} · ${escape(TYPES[r.type]?.label)} · ${escape(r.status)}</small><small class="picker-context">${escape(entityContext(r,index,{approved})||'Standalone record')}</small></span><span class="picker-selected">${selected===r.id?'✓':'→'}</span></button>`).join('')||'<div class="empty"><h3>No matching records</h3><p>Try a shorter name or record ID. Only records eligible for this selection are shown.</p></div>'}</div><footer class="pagination"><span>${view.from}–${view.to} of ${view.total.toLocaleString()}</span><div><button type="button" class="btn sm" data-picker="prev" ${page===1?'disabled':''}>Previous</button><span>Page ${page} of ${view.pageCount}</span><button type="button" class="btn sm" data-picker="next" ${page===view.pageCount?'disabled':''}>Next</button></div></footer>`;
 };
 dialog.addEventListener('click',e=>{e.stopPropagation();const button=e.target.closest('[data-picker]');if(!button)return;const action=button.dataset.picker;if(action==='close'){closeEntityPicker();return;}if(action==='prev'||action==='next'){page+=action==='next'?1:-1;draw();dialog.querySelector('.picker-result')?.focus();return;}if(action==='select'){const id=button.dataset.id;if(id!=='all'&&!records().some(r=>r.id===id))return;closeEntityPicker();onSelect(id);}});
 dialog.addEventListener('input',e=>{e.stopPropagation();if(e.target.id==='entity-picker-search'){query=e.target.value;page=1;draw();}});
 dialog.addEventListener('change',e=>e.stopPropagation());
 dialog.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();closeEntityPicker();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){const nodes=[...dialog.querySelectorAll('.picker-result')];if(!nodes.length)return;e.preventDefault();const pos=nodes.indexOf(document.activeElement);nodes[Math.max(0,Math.min(nodes.length-1,pos+(e.key==='ArrowDown'?1:-1)))]?.focus();}});
 dialog.addEventListener('cancel',e=>{e.preventDefault();closeEntityPicker();});draw();dialog.showModal();dialog.querySelector('input').focus();
}
